-- SYS0013 buttons (8)
MERGE INTO SCM_ADM_MNU_BTN_MPG_M t USING (SELECT 'SYS0013' MNU_ID, 'columns' SHT_NM, 'RETRIEVE' MNU_BTN_CD FROM DUAL) s
   ON (t.MNU_ID=s.MNU_ID AND t.SHT_NM=s.SHT_NM AND t.MNU_BTN_CD=s.MNU_BTN_CD)
 WHEN MATCHED THEN UPDATE SET API_ID='API_SCM0005_GET_COLUMNS', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('SYS0013','columns','RETRIEVE','API_SCM0005_GET_COLUMNS','Y','admin',SYSDATE,'admin',SYSDATE);
